<?php
namespace App\Form\Admin\Clients;
use App\Application\Clients\ClientBranchData; use App\Entity\Clients\ClientCategory; use Symfony\Bridge\Doctrine\Form\Type\EntityType; use Symfony\Component\Form\AbstractType; use Symfony\Component\Form\Extension\Core\Type\{CheckboxType,CollectionType,EmailType,HiddenType,TextareaType,TextType}; use Symfony\Component\Form\FormBuilderInterface; use Symfony\Component\OptionsResolver\OptionsResolver;
final class ClientBranchEntryType extends AbstractType { public function buildForm(FormBuilderInterface $b,array $o):void{$b->add('id',HiddenType::class)->add('code',TextType::class,['label'=>'Código'])->add('name',TextType::class,['label'=>'Nombre de sucursal'])->add('category',EntityType::class,['class'=>ClientCategory::class,'choice_label'=>'name','placeholder'=>'Heredar categoría del cliente','required'=>false])->add('email',EmailType::class,['label'=>'Correo general','required'=>false])->add('notes',TextareaType::class,['label'=>'Notas','required'=>false,'attr'=>['rows'=>2]])->add('isMain',CheckboxType::class,['label'=>'Sucursal principal','required'=>false])->add('addresses',CollectionType::class,['label'=>'Domicilios','entry_type'=>ClientBranchAddressEntryType::class,'allow_add'=>true,'allow_delete'=>true,'by_reference'=>false,'prototype'=>true,'prototype_name'=>'__address__'])->add('phones',CollectionType::class,['label'=>'Teléfonos y fax','entry_type'=>ClientPhoneEntryType::class,'allow_add'=>true,'allow_delete'=>true,'by_reference'=>false,'prototype'=>true,'prototype_name'=>'__branch_phone__'])->add('contacts',CollectionType::class,['label'=>'Contactos','entry_type'=>ClientInlineContactEntryType::class,'allow_add'=>true,'allow_delete'=>true,'by_reference'=>false,'prototype'=>true,'prototype_name'=>'__contact__']);} public function configureOptions(OptionsResolver $r):void{$r->setDefaults(['data_class'=>ClientBranchData::class]);}}
